// Tiny i18n layer: a fixed string table plus one subset font per language.
// Fonts are generated by tools/i18n/build_fonts.py, so a language only costs
// the glyphs that actually appear in the table.
#pragma once
#include <lvgl.h>

enum class Lang : int {
    EN = 0, ZH_HANS, ZH_HANT, JA, KO, FR, DE, ES, RU, LA, COUNT
};

void i18nInit();                       /* load the saved language */
Lang i18nLang();
void i18nSetLang(Lang lang);           /* persists to settings */
const char* i18nLangName(Lang lang);
const char* tr(const char* key);       /* current language text */
const lv_font_t* i18nFont();           /* font covering the current language */
const lv_font_t* i18nFontFor(Lang lang);
